    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            a[i] = (long) in.nval;
        }
        in.nextToken();
        int q = (int) in.nval;
        long[] queries = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken();
            queries[i] = (long) in.nval;
        }
        int[] res = findPositions(a, queries);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append('\n');
        System.out.print(sb);
    }
}
